    // So B is already the solution to original system.

    // Final singularity check: all rows/columns used?
    for (int i = 0; i < N; ++i) {
        if (!ROW_USED[i] || !COL_USED[i]) {
            ISING = 2;
            return;
        }
    }
    ISING = 1;
